"""Build the complete static site. Python is needed only by maintainers."""
from pathlib import Path
from html import escape as esc
from collections import Counter
import json, re, os, argparse, hashlib
ROOT=Path(__file__).resolve().parents[1]
DATA=json.loads((ROOT/'data/forts.json').read_text(encoding='utf-8'))
ATTR=json.loads((ROOT/'data/image-attribution.json').read_text(encoding='utf-8'))
IMAGES={i['slug']:i for i in ATTR}
from enrichment import stars, recommend, detail, event_html
import v4_design as design
import v7_design as modern
import v8_content as content
GALLERY=json.loads((ROOT/"data/gallery-attribution.json").read_text(encoding="utf-8"))
if any(not GALLERY.get(f['slug']) for f in DATA):raise SystemExit('Keep unphotographed fort records in the separate research archive before publishing.')
EVENTS=json.loads((ROOT/"data/heritage-events.json").read_text(encoding="utf-8"))
ILL='assets/images/illustrations/sahyadri.webp'
for f in DATA:
 for key in ['best_season','duration','difficulty']:
  if f.get(key) and str(f[key]).lower().strip() in ['n/a','na','-','not available']:f[key]=None
 p=IMAGES.get(f['source_photo_slug']) or next(iter(GALLERY.get(f['slug'],[])),None)
 f['image']=p['file'] if p else ILL
 f['thumbnail']=p['thumbnail'] if p else ILL.replace('.webp','-600.webp')
 f['image_kind']='photograph' if p else 'illustration'
 f['image_credit']=p or None
 f['url']='forts/'+f['slug']+'/index.html'
 f['directions_url']='https://www.google.com/maps/dir/?api=1&destination='+str(f['latitude'])+','+str(f['longitude']) if f['latitude'] is not None else None
(ROOT/'data/forts.json').write_text(json.dumps(DATA,ensure_ascii=False,indent=2),encoding='utf-8')
(ROOT/'data/forts.js').write_text('window.FORTS='+json.dumps([{k:f[k] for k in ['slug','name','aliases','marathi_name','district','region','type','latitude','longitude','difficulty','difficulty_rating','duration','recommendation','nearest_city','thumbnail','image','image_kind','url','directions_url']} for f in DATA],ensure_ascii=False,separators=(',',':')).replace('</','<\\/')+';',encoding='utf-8')
COUNTS=Counter(f['district'] for f in DATA); VERIFIED=sum(f['latitude'] is not None for f in DATA)
ASSET_VERSIONS={p.relative_to(ROOT).as_posix():hashlib.sha256(p.read_bytes()).hexdigest()[:10] for p in ROOT.rglob('*') if p.is_file() and p.suffix in ['.css','.js']}
def e(s):return esc(str(s if s is not None else ''),quote=True)
def ds(s):return re.sub('[^a-z0-9]+','-',s.lower()).strip('-')
def write(path,content):
 p=ROOT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content,encoding='utf-8')
def image(f,pre='',hero=False):
 return f'<img src="{pre}{e(f["image"] if hero else f["thumbnail"])}" '+(f'srcset="{pre}{e(f["thumbnail"])} 600w, {pre}{e(f["image"])} 1200w" sizes="{("100vw" if hero else "(max-width: 640px) 100vw, (max-width: 1000px) 50vw, 33vw")}" ' if f['image_kind']=='photograph' else '')+f'alt="{e(f["name"])} — {("documentary photograph" if f["image_kind"]=="photograph" else "generic Sahyadri illustration, not a depiction of this fort")}" width="1200" height="800" '+('fetchpriority="high"' if hero else 'loading="lazy" decoding="async"')+'>'
def card(f,pre=''):
 return f'''<article class="fort-card" data-fort="{e(f['slug'])}"><a class="card-image" href="{pre}{f['url']}">{image(f,pre)}<span class="photo-label">{'Photograph' if f['image_kind']=='photograph' else 'Illustration · imagined landscape'}</span><span class="type-badge">{e(f['type'])}</span></a><div class="card-body"><p class="card-location">{e(f['district'])} <span>·</span> {e(f['region'])}</p><h3><a href="{pre}{f['url']}">{e(f['name'])}</a></h3><p>{e(f['recommendation_reason'][:145])}{'…' if len(f['recommendation_reason'])>145 else ''}</p><div class="card-assessment">{stars(f)}{recommend(f)}</div><div class="card-bottom"><a href="{pre}{f['url']}">Discover the story <span aria-hidden="true">↗</span></a><a class="map-link" href="{pre}maps.html?fort={f['slug']}" aria-label="Locate {e(f['name'])} on map">⌖ Map</a></div></div></article>'''
card=design.card
def header(pre,active):
 return modern.header(pre,active)

def footer(pre):
 return f'''<footer class="site-footer"><div class="footer-top"><div><a class="footer-brand" href="{pre}index.html">Swarajya <em>Explorer</em></a><p>Every fort has a story.<br>Come discover yours.</p></div><div><h2>Keep exploring</h2><a href="{pre}forts.html">All {len(DATA)} forts</a><a href="{pre}maps.html">Interactive map</a><a href="{pre}districts.html">Browse districts</a></div><div><h2>Explore thoughtfully</h2><a href="{pre}about.html#responsible">Responsible visits</a><a href="{pre}sources.html">Sources & image credits</a><a href="{pre}tourism-brochure.html">Tourism fort brochure</a><a href="{pre}about.html#method">Our research approach</a><a href="https://www.instagram.com/pranavdecoded/">Instagram ↗</a><a href="mailto:pranavchame1@gmail.com">Email Pranav ↗</a></div></div><div class="footer-bottom"><span>© 2026 Swarajya Explorers · Created by Pranav Vinod Chame · Inspired by Tanshiq and Karan</span><button type="button" data-motion-toggle aria-label="Reduce decorative animations" aria-pressed="false">Motion: On</button><a href="#top">Back to top ↑</a></div></footer>'''
def page(title,desc,body,pre='',active='',mapjs=False,structured=None,ogimage=None,seo_fort=None):
 keywords=content.general_keywords(title)
 if seo_fort:title,desc,keywords=content.fort_meta(seo_fort)
 if ogimage is None:ogimage=next(f['image'] for f in DATA if f['slug']=='rajgad')
 body=design.decorate(body,active,DATA) if active!="About" else body
 body=re.sub(r'<h2>Decorative artwork</h2>.*?<h2>Documentary photographs</h2>','<h2>Documentary photographs</h2>',body,flags=re.S)
 maphead=f'<link rel="stylesheet" href="{pre}assets/vendor/maptiler-sdk.css">' if mapjs else ''
 scripts=f'<script defer src="{pre}js/config.js"></script><script defer src="{pre}js/map.js"></script>' if mapjs else ''
 html=f'''<!doctype html><html lang="en" id="top"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>{e(title)} | Swarajya Explorers</title><meta name="description" content="{e(desc)}"><meta name="keywords" content="{e(keywords)}"><meta name="author" content="Pranav Vinod Chame"><meta name="robots" content="index,follow,max-image-preview:large"><meta name="twitter:title" content="{e(title)} | Swarajya Explorer"><meta name="twitter:description" content="{e(desc)}"><meta name="twitter:image" content="{pre}{e(ogimage)}"><script src="{pre}js/motion-settings.js"></script><meta name="theme-color" content="#17291e"><meta property="og:title" content="{e(title)} | Swarajya Explorers"><meta property="og:description" content="{e(desc)}"><meta property="og:type" content="website"><meta property="og:locale" content="en_IN"><meta property="og:site_name" content="Swarajya Explorers"><meta property="og:image" content="{pre}{e(ogimage)}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="{pre}assets/icons/favicon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;0,700;1,500;1,600&family=Manrope:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="{pre}css/main.css"><link rel="stylesheet" href="{pre}css/responsive.css"><link rel="stylesheet" href="{pre}css/upgrade.css"><link rel="stylesheet" href="{pre}css/v4.css"><link rel="stylesheet" href="{pre}css/experience.css"><link rel="stylesheet" href="{pre}css/v7.css">{maphead}{('<script type="application/ld+json">'+json.dumps(structured,ensure_ascii=False).replace('</','<\\/')+'</script>') if structured else ''}<script defer src="{pre}data/forts.js"></script><script defer src="{pre}js/main.js"></script><script defer src="{pre}js/search.js"></script><script defer src="{pre}js/motion.js"></script><script defer src="{pre}js/transitions.js"></script><script defer src="{pre}js/experience.js"></script><script defer src="{pre}js/navigation.js"></script><script defer src="{pre}js/mascot-loader.js" data-mascot-src="{pre}js/mascot.js"></script>{scripts}</head><body>{header(pre,active)}<main id="main">{body}</main>{footer(pre)}<dialog id="lightbox" aria-label="Photo viewer"><div class="lightbox-tools"><button type="button" class="photo-prev" aria-label="Previous photo">←</button><button type="button" class="photo-next" aria-label="Next photo">→</button><button type="button" class="photo-zoom">Zoom</button><button type="button" class="photo-fullscreen">Fullscreen</button></div><button class="lightbox-close" aria-label="Close photo viewer">Close ×</button><img alt=""><p></p><div class="lightbox-thumbnails" aria-label="Photo thumbnails"></div></dialog></body></html>'''

 def version_asset(match):
  url=match[2];key=url[len(pre):] if pre and url.startswith(pre) else url
  return match[1]+'="'+url+('?v='+ASSET_VERSIONS[key] if key in ASSET_VERSIONS else '')+'"'
 html=html.replace('Swarajya Explorers','Swarajya Explorer')
 return re.sub(r'(href|src)="([^"?]+\.(?:css|js))"',version_asset,html)

def intro(kicker,title,copy):return f'<section class="page-intro wrap"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{copy}</p></section>'
featured_names=['Raigad','Rajgad','Harishchandragad','Sindhudurg Fort','Harihar','Murud-Janjira']
featured=[next(f for f in DATA if f['name']==n) for n in featured_names if any(f['name']==n for f in DATA)]
home=f'''<section class="hero"><img class="hero-art" src="{ILL}" width="1536" height="1024" alt="Imagined Sahyadri fortress at dawn; AI-generated decorative illustration" fetchpriority="high"><div class="hero-shade"></div><div class="hero-content wrap"><p class="eyebrow"><span></span> HISTORY · ADVENTURE · HERITAGE</p><h1>Explore <em>Swarajya</em><br>with us<span class="orange">.</span></h1><p>Beyond the stone walls, a thousand stories.<br>Discover the forts and timeless landscapes of Maharashtra.</p><div class="hero-actions"><a class="button" href="forts.html">Explore the forts <span aria-hidden="true">↗</span></a><a class="text-button" href="maps.html">Open the fort map <span aria-hidden="true">⌖</span></a></div><form class="hero-search" action="forts.html" role="search"><label for="home-search">Where will your next story begin?</label><div><input id="home-search" name="q" type="search" list="fort-suggestions" placeholder="Try Raigad, Harihar or a district…"><datalist id="fort-suggestions">{''.join('<option value="'+e(f['name'])+'">' for f in DATA)}</datalist><button type="submit" aria-label="Search forts">Search ↗</button></div></form></div><span class="hero-caption">THE LAND OF LEGENDS</span><span class="art-caption">AI-generated heritage illustration · imagined landscape</span></section>
<div class="stats-strip"><div><strong>{len(DATA)}</strong><span>forts to discover</span></div><div><strong>{len(COUNTS)}</strong><span>districts to explore</span></div><div><strong>One</strong><span>extraordinary heritage</span></div><a href="maps.html">Find your way into history <span>⌖</span></a></div>
<section class="wrap section"><div class="section-heading"><div><p class="eyebrow">YOUR JOURNEY STARTS HERE</p><h2>Walk through <em>history.</em></h2></div><p>From the heights of the Sahyadris to the shores of the Konkan, find a place that stays with you.</p></div><div class="feature-row"><div><span>01 / DISCOVER</span><h3>Find your fort</h3><p>Follow a familiar name or discover somewhere new in our sourced fort directory.</p></div><div><span>02 / CONNECT</span><h3>Explore its story</h3><p>Meet the landscapes, architecture and histories behind the stone walls.</p></div><div><span>03 / EXPLORE</span><h3>Plan thoughtfully</h3><p>Locate the monument, check local conditions and travel with respect for the place.</p></div></div></section>
<section class="wrap section featured"><div class="section-heading"><div><p class="eyebrow">PLACES THAT TELL OUR STORY</p><h2>Iconic forts.<br><em>Extraordinary journeys.</em></h2></div><a class="outline-button" href="forts.html">Discover all forts ↗</a></div><div class="card-grid">{''.join(card(f) for f in featured)}</div></section>
<section class="map-teaser"><div class="wrap map-teaser-grid"><div><p class="eyebrow">LET CURIOSITY BE YOUR COMPASS</p><h2>A landscape<br>made for <em>exploring.</em></h2><p>Zoom into Maharashtra’s fort landscape. Discover hilltop strongholds, coastal defences and the stories that connect them.</p><a class="button" href="maps.html">Explore the interactive map ↗</a><p class="small">{VERIFIED} source-referenced locations · MapTiler</p></div><div class="map-illustration" aria-label="Fort map preview"><div class="map-contours"></div><span class="mini-pin pin-a">⌖<small>Salher</small></span><span class="mini-pin pin-b">⌖<small>Raigad</small></span><span class="mini-pin pin-c">⌖<small>Sindhudurg</small></span><span class="map-preview-label">MAHARASHTRA<br><small>Schematic preview · open the geographic map</small></span><a href="maps.html" class="map-open">Open map ↗</a></div></div></section>
<section class="wrap section"><div class="section-heading"><div><p class="eyebrow">MANY REGIONS. COUNTLESS STORIES.</p><h2>Choose a <em>district.</em></h2></div><a class="plain-link" href="districts.html">All {len(COUNTS)} districts ↗</a></div><div class="district-grid">{''.join(f'<a class="district-tile" href="districts/{ds(d)}/index.html"><span>{str(i+1).zfill(2)}</span><h3>{e(d)}</h3><p>{COUNTS[d]} documented forts <b>↗</b></p></a>' for i,d in enumerate(['Pune','Raigad','Nashik','Satara','Ratnagiri','Sindhudurg']))}</div></section>
<section class="heritage-banner"><div class="wrap"><p class="eyebrow">A LEGACY WORTH CARING FOR</p><h2>Leave only footprints.<br>Carry the <em>stories.</em></h2><p>These landscapes are living heritage. Walk gently, respect local communities and help keep the forts beautiful for those who follow.</p><a class="text-button" href="about.html#responsible">Explore responsibly ↗</a></div></section>'''
home=re.sub(r'<div class="map-illustration".*?</div></div></section>', '<div class="map-preview-shell"><div id="fort-preview" role="region" aria-label="Maharashtra fort map preview"></div><a href="maps.html" class="map-open">Open the full map ↗</a></div></div></section>', home, flags=re.S)
trekking=[f for name in ['Lohagad','Tikona','Torna Fort'] for f in DATA if f['name']==name]
home=home.replace('<section class="heritage-banner">','<section class="wrap section trekking"><div class="section-heading"><div><p class="eyebrow">FOLLOW THE MOUNTAIN PATHS</p><h2>Take the <em>higher path.</em></h2></div><a class="plain-link" href="forts.html?type=Hill+fort">Explore hill forts ↗</a></div><div class="card-grid">'+''.join(card(f) for f in trekking)+'</div></section><section class="heritage-banner">')
home=home.replace('<div id="fort-preview"', '<div id="fort-preview"')
home += '<section class="wrap section"><p class="eyebrow">THE PEOPLE AND PLACES OF SWARAJYA</p><h2>History that lives <em>in the landscape.</em></h2>'+''.join(event_html(ev) for ev in EVENTS[:3])+'<p><a class="outline-button" href="history.html">Explore Maratha history ↗</a></p></section>'
home=design.home(DATA,GALLERY,EVENTS)
write('index.html',page('Maharashtra forts, stories & adventures','Discover Maharashtra’s forts with sourced histories, genuine photographs, district guides and an interactive fort map.',home,active='Home',mapjs=True))
def controls(district=None):
 return f'''<form id="filters" class="filters" role="search"><div class="filter-search"><label for="search">Search forts</label><input id="search" name="q" type="search" placeholder="Name, alternate name, district or region" list="directory-suggestions"><datalist id="directory-suggestions">{''.join('<option value="'+e(f['name'])+'">' for f in DATA)}</datalist></div><div><label for="district">District</label><select id="district" name="district"><option value="">All districts</option>{''.join('<option'+(' selected' if d==district else '')+'>'+e(d)+'</option>' for d in sorted(COUNTS))}</select></div><div><label for="region">Region</label><select id="region" name="region"><option value="">All regions</option>{''.join('<option>'+e(r)+'</option>' for r in sorted(set(f['region'] for f in DATA)))}</select></div><div><label for="type">Fort type</label><select id="type" name="type"><option value="">All types</option>{''.join('<option>'+e(t)+'</option>' for t in sorted(set(f['type'] for f in DATA)))}</select></div><div><label for="difficulty">Trek grade</label><select id="difficulty" name="difficulty"><option value="">All grades</option><option>Easy</option><option>Moderate</option><option>Difficult</option><option>Very Difficult</option><option value="unknown">Not documented</option></select></div><div><label for="sort">Sort by</label><select id="sort" name="sort"><option value="name">Name A–Z</option><option value="district">District</option></select></div><label>Visit recommendation<select name="recommendation"><option value="">All recommendations</option><option>Visit</option><option>Recommended</option><option>Must Visit</option><option>Most Recommended</option></select></label><label class="check-label"><input type="checkbox" id="saved-only"> Saved forts</label><button type="reset" class="clear-button">Clear filters ↺</button></form>'''
def directory(district=None,pre=''):
 subset=[f for f in DATA if not district or f['district']==district]
 return intro('FOLLOW YOUR CURIOSITY',e(district)+' forts' if district else 'Find your next <em>adventure.</em>',f'Explore {len(subset)} documented forts'+(' in '+e(district) if district else ' across Maharashtra')+'. Search by name, landscape or district, and discover the story behind each place.')+f'''<section class="wrap directory" data-directory data-fixed-district="{e(district or '')}">{controls(district)}<div class="results-bar"><p id="results-count" role="status" aria-live="polite">{len(subset)} forts to explore</p><a href="{pre}maps.html{('?district='+urllib_quote(district)) if district else ''}" class="plain-link">Explore on map ⌖</a></div><div id="results" class="card-grid">{''.join(card(f,pre) for f in subset)}</div><div id="no-results" class="empty-state" hidden><h2>No forts found</h2><p>Try another name or clear a filter to explore more places.</p><button id="empty-clear" class="outline-button">Clear all filters</button></div><button id="load-more" class="outline-button load-more" hidden>Show more forts</button><noscript><p>All forts are listed above. Enable JavaScript for instant filtering and local favourites.</p></noscript><p class="data-note">Trek grades are source descriptions, not current safety assessments. Missing details are shown as undocumented. <a href="{pre}about.html#method">Read our research approach</a>.</p></section>'''
from urllib.parse import quote as urllib_quote
write('forts.html',page('Explore all Maharashtra forts',f'Search {len(DATA)} Maharashtra forts by name, district, region, type and documented trek grade.',directory(),active='Explore forts'))
for d in sorted(COUNTS):write('districts/'+ds(d)+'/index.html',page(d+' forts',f'Explore {COUNTS[d]} forts in {d}, Maharashtra, with history, photographs and map locations.',directory(d,'../../'),pre='../../',active='Districts'))
distpage=intro('A DIFFERENT STORY IN EVERY DIRECTION','Explore by <em>district.</em>',f'{len(COUNTS)} districts represented in this catalogue.')
for region in sorted(set(f['region'] for f in DATA)):
 districts=[d for d in sorted(COUNTS) if any(f['district']==d and f['region']==region for f in DATA)]
 distpage+='<section class="wrap section"><p class="eyebrow">'+e(region)+'</p><div class="district-grid">'+''.join('<article class="district-tile"><span>'+str(COUNTS[d])+' documented forts</span><h2>'+e(d)+'</h2><p>'+e(', '.join(f['name'] for f in DATA if f['district']==d)[:110])+'</p><p><a href="districts/'+ds(d)+'/index.html">Browse forts ↗</a> · <a href="maps.html?district='+urllib_quote(d)+'">View on map ⌖</a></p></article>' for d in districts)+'</div></section>'
write('districts.html',page('Maharashtra forts by district','Browse district guides to forts in the Konkan, Sahyadris, Vidarbha, Marathwada and western Maharashtra.',distpage,active='Districts'))
mapbody=intro('ONE MAP. HUNDREDS OF STORIES.','Find your way into <em>history.</em>',f'Explore {VERIFIED} source-referenced fort locations. Select a result or a marker to begin.')+f'''<section class="wrap map-section">{controls()}<div class="map-layout"><aside class="map-sidebar" aria-label="Fort map search results"><p id="results-count" role="status" aria-live="polite"></p><div id="map-results"></div></aside><div class="map-column"><div id="fort-map" aria-label="Interactive Maharashtra fort map" role="region"></div><p id="map-status" class="map-status" role="status">Loading the fort map…</p><div class="map-legend"><span><i></i> Fort location</span><span><i class="selected"></i> Selected fort</span><span>Numbered circles group nearby forts. Zoom in to explore.</span></div></div></div><noscript><p>Enable JavaScript for the interactive map, or <a href="forts.html">browse every fort in the static directory</a>.</p></noscript><p class="data-note">Coordinates follow the linked geographical sources and are not a field survey. Pins identify monuments, not trailheads. Forts with missing or conflicting locations remain searchable but are not plotted. <a href="sources.html">Sources and credits</a>.</p></section>'''
write('maps.html',page('Interactive Maharashtra fort map','Explore Maharashtra forts on a searchable MapTiler outdoor and terrain map with fort details and directions.',mapbody,active='Fort map',mapjs=True))
def fact(label,value):return f'<div><dt>{e(label)}</dt><dd>{e(value or "Not documented")}</dd></div>'
for f in DATA:
 pre='../../';refs=''.join(f'<li><a href="{e(r["url"])}" target="_blank" rel="noopener noreferrer">{e(r["title"])} ↗</a></li>' for r in f['references'])
 credit=f['image_credit']; phototext=(f'Photograph: {e(credit["artist"])} · <a href="{e(credit["source"])}">Wikimedia Commons</a> · <a href="{e(credit["license_url"] or credit["source"])}">{e(credit["license"])}</a>. Resized to WebP.' if credit else 'AI-generated generic Sahyadri illustration. This artwork does not depict or reconstruct '+e(f['name'])+'.')
 near=[a for a in DATA if a['district']==f['district'] and a['slug']!=f['slug']]
 if f['latitude'] is not None:near.sort(key=lambda a:(a['latitude']-f['latitude'])**2+(a['longitude']-f['longitude'])**2 if a['latitude'] is not None else 1000)
 body=f'''<div class="wrap breadcrumb"><a href="../../index.html">Home</a> / <a href="../../districts/{ds(f['district'])}/index.html">{e(f['district'])}</a> / <span>{e(f['name'])}</span></div><section class="fort-hero wrap"><div class="fort-hero-photo">{image(f,pre,True)}<span class="photo-label">{'Documentary photograph' if credit else 'Illustration · imagined landscape'}</span></div><div class="fort-hero-copy"><p class="eyebrow">{e(f['region'])} · {e(f['type'])}</p><h1>{e(f['name'])}</h1><p class="lead">{e(f['significance'])}</p>{('<p class="alias">Also known as '+e(', '.join(f['aliases']))+'</p>') if f['aliases'] else ''}<div class="fort-actions"><a class="button" href="../../maps.html?fort={f['slug']}">View on map ⌖</a><button class="outline-button favorite" data-save="{f['slug']}" aria-pressed="false">♡ Save fort</button><button class="share-button" type="button">Copy link ↗</button></div><p id="share-status" role="status" aria-live="polite"></p></div></section><div class="wrap image-credit">{phototext}</div><section class="wrap quick-facts"><dl>{fact('District',f['district'])}{fact('Fort type',f['type'])}{fact('Source elevation',f['elevation'])}{fact('Trek grade',f['difficulty'])}</dl></section><div class="wrap detail-layout"><article><section class="detail-section"><p class="eyebrow">BEHIND THE STONE WALLS</p><h2>The story of {e(f['name'])}</h2>{('<p>'+e(f['history'])+'</p>') if f['history'] else '<p class="source-note-label">A short excerpt from the linked historical account:</p><blockquote>'+e(f['history_excerpt'])+'</blockquote><p class="small">This entry currently has a source note. The full historical account and its references are linked below.</p>'}{('<h3>Historical associations</h3><p>The source account mentions '+e(', '.join(f['rulers']))+'. These associations do not imply that every named power built this fort.</p>') if f['rulers'] else ''}{('<h3>Recorded events</h3><ul>'+''.join('<li>'+e(a)+'</li>' for a in f['events'])+'</ul>') if f['events'] else ''}{('<p>'+e(f['shivaji_connection'])+'</p>') if f['shivaji_connection'] else ''}</section><section class="detail-section"><p class="eyebrow">READING THE LANDSCAPE</p><h2>Architecture & landmarks</h2>{('<p>Features discussed in the source account include:</p><ul class="feature-list">'+''.join('<li>'+e(a)+'</li>' for a in f['architecture'])+'</ul><p class="small">Survival and visitor access vary; this is a historical feature list rather than a current condition survey.</p>') if f['architecture'] else '<p>Detailed architectural information is not yet documented in this entry. Consult the historical references before interpreting the remains.</p>'}</section><section class="detail-section"><p class="eyebrow">BEFORE YOU GO</p><h2>Travel & trekking</h2><dl class="travel-facts">{fact('Nearest documented settlement',f['nearest_settlement'])}{fact('Source trek duration',f['duration'])}{fact('Source season advice',f['best_season'])}</dl><p>{e(f['how_to_reach'] or 'Route and transport details are not verified in this entry. Use the source guide and check with local authorities or a local guide for current access.')}</p><div class="notice"><h3>Explore with care</h3><p>{e(f['safety'])}</p><a href="../../about.html#responsible">Responsible exploration ↗</a></div></section><section class="detail-section"><h2>{'A closer look' if credit else 'About this illustration'}</h2><figure class="gallery-photo"><button class="gallery-open" data-image="../../{e(f['image'])}" data-caption="{e(f['name'])+' — '+('documentary photograph' if credit else 'generic AI illustration; not this fort')}" aria-label="Enlarge {e(f['name'])} image">{image(f,pre)}</button><figcaption>{phototext}</figcaption></figure></section><section id="references" class="detail-section references"><h2>Sources & further reading</h2><ol>{refs}</ol><p class="small">Source review: {f['reviewed']}. Coordinates: {e(f['coordinate_status'])}. {e(f['editorial_status'])} entry. Open encyclopaedic sources can contain errors; this is not an archaeological survey.</p><a href="../../sources.html">Image credits and editorial method ↗</a></section></article><aside class="visit-card"><p class="eyebrow">PLAN YOUR EXPLORATION</p><h2>{e(f['name'])}</h2><p>{e(f['district'])}, Maharashtra</p>{('<p class="coordinates">'+str(round(f['latitude'],6))+'° N<br>'+str(round(f['longitude'],6))+'° E</p>') if f['latitude'] is not None else '<p class="small">Verified location unavailable. No marker or directions are provided.</p>'}<a class="button" href="../../maps.html?fort={f['slug']}">Explore on map ⌖</a>{('<a class="outline-button" href="'+e(f['directions_url'])+'" target="_blank" rel="noopener noreferrer">Google Maps directions ↗</a>') if f['directions_url'] else ''}<p class="small">Confirm the safe approach locally. A monument pin is not a trail recommendation.</p></aside></div><section class="wrap section"><div class="section-heading"><div><p class="eyebrow">KEEP THE JOURNEY GOING</p><h2>More in <em>{e(f['district'])}.</em></h2></div><a href="../../districts/{ds(f['district'])}/index.html">Explore this district ↗</a></div><div class="card-grid">{''.join(card(a,pre) for a in near[:3])}</div>{('<p>Explore <a href="../../forts.html">all Maharashtra forts</a>.</p>') if not near else ''}</section>'''
